'use strict';
const scenarioData=new Map(),simulations=new Map();let period=100;
document.title='IgnispyroFloods · Chuva, escoamento e população';
document.querySelector('.wordmark span').innerHTML='Ignispyro<b>Floods</b>';
const control=document.createElement('div');control.className='select-row';control.innerHTML='<label for="period">Cenário de inundação · não é previsão atual</label><select id="period"><option value="20">T20 · APA</option><option value="100" selected>T100 · APA</option><option value="1000">T1000 · APA</option><option value="10" disabled>T10 · sem cartografia ligada</option></select><p class="caption">Os períodos de retorno não são inferidos da chuva da estação.</p>';
$('view').parentElement.after(control);
const note=document.createElement('p');note.className='caption';note.innerHTML='<a href="report.html">Relatório e figuras ↗</a> · <a href="https://github.com/dsantananet/ignispyro-floods/tree/main/docs">Estudo e fontes ↗</a>';
document.querySelector('.notice').after(note);
const originalRender=render;render=function(){originalRender();$('legend').innerHTML=$('legend').innerHTML.replaceAll('T100','T'+period);};
const originalShow=showParish;
showParish=function(code,fly=true){originalShow(code,fly);let f=data.parishes.features.find(f=>f.properties.dtmnfr===code);if(!f)return;let p=f.properties,root=$('detail-content');root.innerHTML=root.innerHTML.replaceAll('T100','T'+period).replace('Censos 2021 · INE 0014584, apurados para a geografia de freguesias de 2025.','Censos 2021 · '+E(p.population_source)+'. Contagens etárias no território compatível; ver método.');
let pop=document.createElement('div');pop.innerHTML='<h3>Vulnerabilidade etária · residentes</h3><dl>'+metric('0–14 anos',num(p.children_0_14,0))+metric('65 ou mais anos',num(p.elderly_65_plus,0))+metric('Soma dos dois grupos',num(p.vulnerable_age_count,0))+'</dl><p>Indicador etário de suscetibilidade. Não inclui todas as dimensões da vulnerabilidade nem mede visitantes.</p><button id="exposure-button">Calcular exposição BGRI · T'+period+'</button><div id="exposure-result"></div>';root.querySelector('h3:nth-of-type(3)')?.before(pop);
let desc=root.querySelector('details');if(desc){let b=p.basin_ids.map(id=>simulations.get(id)).filter(Boolean).sort((a,b)=>(b.rainfall_pressure??-1)-(a.rainfall_pressure??-1))[0];if(b){let out=document.createElement('div');out.innerHTML='<h3>Simulação automática · chuva observada</h3><dl>'+metric('Volume de chuva em 24 h',b.rainfall_volume_m3===null?'n.d.':num(b.rainfall_volume_m3/1e6,3)+' hm³')+b.runoff_sensitivity.map(r=>metric('Escoamento CN '+r.cn,r.volume_m3===null?'n.d.':num(r.volume_m3/1e6,3)+' hm³')).join('')+'</dl><p>Gama de sensibilidade, não intervalo probabilístico. '+b.station_count+' estações completas. CN não calibrados; não calcula T nem mancha atual.</p>';desc.before(out);}}
root.insertAdjacentHTML('beforeend','<h3>População presente e fluxos</h3><p>Camada comum aos riscos: ainda sem dados de mobilidade ligados. Meta requer acordo de acesso; MEO, NOS e Vodafone disponibilizam soluções agregadas. Residentes, presenças e fluxos mantêm unidades distintas.</p><a href="https://github.com/dsantananet/ignispyro-floods/blob/main/docs/MOBILIDADE_E_POPULACAO_PRESENTE.md" target="_blank" rel="noopener">Fontes e viabilidade ↗</a>');
const btn=$('exposure-button');if(btn)btn.onclick=async()=>{const result=$('exposure-result'),chosenPeriod=period;btn.disabled=true;result.textContent='A consultar subsecções BGRI e a intersectar a mancha…';try{let e=await FloodExposure.calculate(f,scenarioData.get(chosenPeriod)||data.risk,chosenPeriod);if(selected!==code||period!==chosenPeriod)return;result.innerHTML='<h3>Estimativa espacial · T'+chosenPeriod+'</h3><dl>'+metric('Residentes na freguesia ≈',num(e.residents,0))+metric('Residentes na mancha ≈',e.coverage?num(e.exposed,0):'Sem cobertura')+metric('0–14 anos na mancha ≈',e.coverage?num(e.exposed_children,0):'Sem cobertura')+metric('65+ na mancha ≈',e.coverage?num(e.exposed_elderly,0):'Sem cobertura')+metric('Subsecções analisadas',String(e.subsections))+'</dl><p>Estimativa por repartição de área das subsecções BGRI2021, assumindo população uniforme. Não é uma contagem de pessoas atualmente inundadas. A mancha de cenário é simplificada; a análise científica usará geometria original e dados de edifícios.</p>';}catch(e){result.textContent='Exposição indisponível: '+e.message;}finally{btn.disabled=false;}};bindRunoff(p.basin_ids.map(id=>basinState.get(id)).filter(Boolean).sort((a,b)=>(b.pressure??-1)-(a.pressure??-1))[0]);};
function riverPressure(){if(!map?.getSource('rivers'))return;for(let f of data.rivers.features){let states=(f.properties.basin_ids||[]).map(id=>basinState.get(id)).filter(Boolean),valid=states.filter(b=>b.pressure!==null);f.properties.pressure=valid.length?Math.max(...valid.map(b=>b.pressure)):null;}map.getSource('rivers').setData(data.rivers);}
const originalCompute=compute;compute=function(){originalCompute();riverPressure();};
async function enhance(){await Promise.all([20,1000].map(async t=>scenarioData.set(t,await get(t===20?'risk20.geojson':'risk1000.geojson'))));let sim=await get('simulation.json');for(let b of sim.basins)simulations.set(b.id,b);data.rivers=await get('rivers.geojson');scenarioData.set(100,data.risk);let add=()=>{if(map.getSource('rivers'))return;map.addSource('rivers',{type:'geojson',data:data.rivers});map.addLayer({id:'rivers',type:'line',source:'rivers',paint:{'line-color':['match',['coalesce',['get','pressure'],0],3,'#e88939',4,'#c74667','#168ec0'],'line-width':['match',['coalesce',['get','pressure'],0],3,3,4,4,1.4],'line-opacity':.9}},'rain');riverPressure();let label=document.createElement('label');label.innerHTML='<input type="checkbox" data-layer="rivers" checked> Rios · azul / pressão de chuva';document.querySelector('fieldset').append(label);label.querySelector('input').onchange=e=>map.setLayoutProperty('rivers','visibility',e.target.checked?'visible':'none');};if(map.getSource('rain'))add();else map.once('load',add);
$('period').onchange=()=>{period=Number($('period').value);data.risk=scenarioData.get(period);for(let f of data.parishes.features){f.properties.scenario_risk=f.properties['risk_t'+period];f.properties.scenario_sites=f.properties['sites_t'+period];}map.getSource('risk').setData(data.risk);compute();render();$('parish-count').parentElement.querySelector('span').textContent='freguesias no cenário T'+period;if(selected)showParish(selected,false);};
$('method-content').insertAdjacentHTML('beforeend','<h3>Dados populacionais usados neste lançamento</h3><p>BGRI2021 obtida numa cópia alojada em ArcGIS, com 3 092 unidades de freguesia e total nacional 10 343 066. A compatibilidade com CAOP2025 foi testada por sobreposição com CAOP2021, com IoU mínimo de 99,5%; é um critério exploratório, não certificação oficial. Nos territórios alterados, as contagens ficam por harmonizar, podendo ser estimadas por subsecções no botão de exposição. O INE 0014584 foi identificado mas a sua extração final nesta rede não ficou disponível.</p><p>Rios: azul é a rede geográfica normal. Laranja/vermelho e maior espessura representam pressão meteorológica elevada/muito elevada na bacia, uma triagem experimental. A largura desenhada não é a largura física da inundação; as manchas selecionadas T20/T100/T1000 são cenários APA independentes da chuva de hoje. T10 não está disponível neste serviço.</p>');
}
const ready=setInterval(()=>{if(data.parishes&&map){clearInterval(ready);enhance().catch(e=>{console.warn(e);$('updated').textContent+=' · camadas adicionais indisponíveis';});}},200);
